  'Student records':['Student ID · admission number · passport photograph','Surname · first and middle name · date of birth · gender','Nationality · state of origin · LGA · address','Student phone/email · religion only if required','Admission date/session · current class/arm · previous school/class','Registered subjects · senior department · status · house (if used)','Parent/guardian name · relationship · phone · email · address · occupation','Parent ID · linked siblings · emergency contact','Allergies and necessary medical information (restricted)','Blood group/genotype only if required and securely handled','Doctor or hospital contact where applicable','Attendance · results · fees · discipline · awards','Clubs · leadership · documents · promotion history'],
  'Results approval':['Session · term · class · arm · class size','Subject · CA/Test · examination · total','Grade · remark · position (if used)','Average · attendance · comments','Promotion status · next class','Teacher → form teacher → academic review → principal approval'],
  'Results':['Subject score · CA/Test · examination','Total · grade · remark','Total score · average · attendance','Teacher and principal comments','Promotion status · next class · approval'],
  'Attendance':['Present · absent · late','Excused · sick · school activity','Days school opened · present · absent · late','Attendance percentage · absence alert','Authorized correction and audit record'],
  'Timetable':['Session · term · class · arm','Day · period · start and end time','Subject · teacher · room or venue','Mobile view · print/download'],
  'Assignments':['Title · subject · class · teacher','Instructions · date assigned · due date','Attachments · marks · feedback','Pending → submitted → marked → returned'],
  'Documents':['Approved term and session results','Transcripts · timetables · school calendar','Assignments · notices · handbook · forms','Invoices · fee statements · receipts','Certificates after approval · reference number'],
  'Gallery approvals':['Title · category · date · description','Session · term · event · uploader','Approval status · authorized publication'],
