  'Score entry':['Assigned class and subject','CA/test and examination scores','Configured weighting and grading scale','Submit for form-teacher and academic review'],
  'Fees & payments':['Authorized role only','Fees · invoice · payment · receipt','Statement · payment history'],
  'Audit log':['User · action · previous and new values','Reason · date/time · approving officer']
