function PortalWorkspace({role,setRole,navigate,allowRoleSwitch=true,accountName,accountEmail,onSignOut}) {
  const nav=roleNavigation[role]||roleNavigation.Student;
  const slug=item=>item.toLowerCase().replaceAll(' & ','-').replaceAll(' ','-');
  const sub=window.location.pathname.split('/')[3];
  const active=sub?nav.find(item=>slug(item)===sub)||'Overview':'Overview';
  const go=item=>navigate(item==='Overview'?'/portal/'+portalSlug(role):'/portal/'+portalSlug(role)+'/'+slug(item));
  const icons=[LayoutDashboard,Users,GraduationCap,CalendarDays,ClipboardCheck,Bell,ReceiptText,ShieldCheck];
  return <div className="portal"><aside><button className="brand side-brand" onClick={()=>navigate('/')}><Crest small/><span><b>MAVERICK</b><em>{accountEmail?'SCHOOL PORTAL':'PORTAL PREVIEW'}</em></span></button><div className="user"><div className="avatar">{role[0]}</div><div><b>{accountName||role+' workspace'}</b><small>{accountEmail||'Sample interface · no live account'}</small></div></div><div className="side-nav">{nav.map((item,index)=>{const Icon=icons[index%icons.length];return <button key={item} className={active===item?'active':''} onClick={()=>go(item)}><Icon size={18}/>{item}</button>;})}</div>{allowRoleSwitch&&<div className="switcher"><small>PREVIEW ROLE</small><select aria-label="Choose portal preview role" value={role} onChange={e=>{setRole(e.target.value);navigate('/portal/'+portalSlug(e.target.value));}}>{portalRoles.map(item=><option key={item}>{item}</option>)}</select></div>}</aside><div className="portal-main"><div className="topbar"><div><button className="back" onClick={()=>navigate('/')}>← Website</button><p>{accountEmail?'Authenticated school account':'Demonstration only · sample information'}</p></div><div className="top-actions">{!accountEmail&&<><button aria-label="View announcements" onClick={()=>go(nav.includes('Announcements')?'Announcements':'Overview')}><Search size={19}/></button><button className="notification" aria-label="View notices" onClick={()=>go(nav.includes('Announcements')?'Announcements':'Overview')}><Bell size={19}/><i/></button></>}<div className="avatar">{role[0]}</div>{onSignOut&&<button className="sign-out" onClick={onSignOut}>Sign out</button>}</div></div><section className="dashboard">{active==='Overview'?accountEmail?<ConnectedOverview role={role} accountName={accountName} nav={nav} go={go}/>:<><div className="dashboard-heading"><div><p className="eyebrow blue">{role.toUpperCase()} DEMO PREVIEW</p><h1>{role} workspace</h1><p>Sample navigation for the role-based school system requirements.</p></div></div><div className="detail-columns portal-module-grid">{nav.filter(item=>item!=='Overview').slice(0,8).map(item=><article key={item}><span className="level-tag">{role} access preview</span><h3>{item}</h3><p>{featureDetails[item]?.[1]||'This role-based section will contain information permitted for this user in the live system.'}</p><button className="link" onClick={()=>go(item)}>Open section <ChevronRight size={15}/></button></article>)}</div><article className="policy-note"><h3>Preview boundary</h3><p>This interface has no live authentication or database. All account controls, student details, results, fee records, uploads and permissions must be connected to a secure backend before operational use.</p></article></>:<RoleFeaturePanel active={active} role={role} navigate={navigate} connected={Boolean(accountEmail)}/>}</section></div></div>;
}
function ConnectedOverview({role,accountName,nav,go}) { return <><div className="dashboard-heading"><div><p className="eyebrow blue">AUTHENTICATED ACCOUNT</p><h1>Welcome, {accountName||role}.</h1><p>Your session and role profile are connected to the school database.</p></div></div><article className="policy-note"><h3>Foundation connected</h3><p>Sign-in, profile lookup and database role checks are active. Student, attendance and announcement policies are in the pilot schema. Screens to read and manage those records are the next build step.</p></article><h2 className="section-title">Your role areas</h2><div className="detail-columns portal-module-grid">{nav.filter(item=>item!=='Overview').map(item=><article key={item}><span className="level-tag">{role}</span><h3>{item}</h3><p>{featureDetails[item]?.[1]||'This section will show data permitted for your role after its workflow is connected.'}</p><button className="link" onClick={()=>go(item)}>Open section <ChevronRight size={15}/></button></article>)}</div></>; }
const recoveryUrl = new URL('/login?mode=reset', window.location.origin).toString();
const studentLoginEmail = schoolId => {
  const normalized = schoolId.trim().toUpperCase();
  if (!/^MIC\/\d{4}\/\d{4}$/.test(normalized)) {
    throw new Error('Enter your school ID in the format MIC/YYYY/NNNN.');
  }
  return `${normalized.toLowerCase().replaceAll('/', '-')}@students.maverick-international-college-port.vercel.app`;
};
function LoginPage({navigate}) { const query=new URLSearchParams(window.location.search); const [mode,setMode]=useState(query.get('mode')==='reset'?'reset':'sign-in'); const [loginRole,setLoginRole]=useState(['student','parent','teacher','admin'].includes(query.get('role'))?query.get('role'):'student'); const [email,setEmail]=useState(''); const [password,setPassword]=useState('');const [showPassword,setShowPassword]=useState(false); const [notice,setNotice]=useState(''); const [error,setError]=useState(''); const [busy,setBusy]=useState(false);
  const isStudentLogin=loginRole==='student';
  const passwordChecks={length:password.length>=8,lowercase:/[a-z]/.test(password),uppercase:/[A-Z]/.test(password),number:/\d/.test(password),symbol:/[^A-Za-z0-9]/.test(password)};
  useEffect(()=>{if(!supabaseConfigured)return;const {data:{subscription}}=supabase.auth.onAuthStateChange(event=>{if(event==='PASSWORD_RECOVERY')setMode('reset');});return()=>subscription.unsubscribe();},[]);
  const expectedRoles={student:['student'],parent:['parent'],teacher:['teacher','form_teacher'],admin:['super_admin','principal','vice_principal','admin','bursar','librarian']};
  const submit=async e=>{e.preventDefault();setError('');setNotice('');if(!supabaseConfigured){setError('The school has not connected a Supabase project yet.');return;}setBusy(true);try{if(mode==='sign-in'){const schoolId=isStudentLogin?email.trim().toUpperCase():'';const signInEmail=isStudentLogin?studentLoginEmail(schoolId):email.trim();const {data,error:authError}=await supabase.auth.signInWithPassword({email:signInEmail,password});if(authError)throw authError;const {data:profile,error:profileError}=await supabase.from('profiles').select('role').eq('id',data.user.id).single();if(profileError){await supabase.auth.signOut();throw profileError;}if(!expectedRoles[loginRole].includes(profile.role)){await supabase.auth.signOut();throw new Error(`This account is registered for ${roleFromSlug(profile.role)} access. Choose the matching portal.`);}if(isStudentLogin){const {data:student,error:studentError}=await supabase.from('students').select('student_number').eq('profile_id',data.user.id).maybeSingle();if(studentError||student?.student_number?.toUpperCase()!==schoolId){await supabase.auth.signOut();throw studentError||new Error('This school ID is not linked to the signed-in student account. Ask the school office to check the account setup.');}}navigate('/portal');}else if(mode==='forgot'){if(isStudentLogin)throw new Error('Student passwords are reset by the school office. Please ask an authorized administrator for help.');const {error:authError}=await supabase.auth.resetPasswordForEmail(email.trim(),{redirectTo:recoveryUrl});if(authError)throw authError;setNotice('If this address belongs to a school account, password recovery instructions have been sent.');}else{if(!Object.values(passwordChecks).every(Boolean))throw new Error('Please meet every password requirement shown below.');const {data:{session}}=await supabase.auth.getSession();if(!session)throw new Error('Open the latest password recovery link from your email first.');const {error:authError}=await supabase.auth.updateUser({password});if(authError)throw authError;setNotice('Your password has been updated. You can now sign in.');setPassword('');setMode('sign-in');window.history.replaceState({},'', '/login');}}catch(authError){setError(authError.message||'Authentication could not be completed.');}finally{setBusy(false);}};
  return <main className="auth-page"><section className="auth-card"><button className="brand auth-brand" onClick={()=>navigate('/')}><Crest small/><span><b>MAVERICK</b><em>INTERNATIONAL COLLEGE</em></span></button><p className="eyebrow blue">SCHOOL ACCOUNT</p><h1>{mode==='sign-in'?'Sign in to your portal':mode==='forgot'?'Reset your password':'Choose a new password'}</h1><p className="auth-intro">{mode==='sign-in'?(isStudentLogin?'Enter the school ID and password issued by the school.':'Choose your school role and use the email and password issued for your account. Student and family self-registration is disabled.'):mode==='forgot'?'Enter the email address connected to your school account.':'Set a new password for your school account.'}</p>{mode==='sign-in'&&<div className="login-roles" role="group" aria-label="Choose your portal"><button type="button" className={loginRole==='student'?'selected':''} onClick={()=>setLoginRole('student')}><GraduationCap size={18}/>Student</button><button type="button" className={loginRole==='parent'?'selected':''} onClick={()=>setLoginRole('parent')}><Users size={18}/>Parent</button><button type="button" className={loginRole==='teacher'?'selected':''} onClick={()=>setLoginRole('teacher')}><BookOpen size={18}/>Teacher</button><button type="button" className={loginRole==='admin'?'selected':''} onClick={()=>setLoginRole('admin')}><ShieldCheck size={18}/>Admin / Staff</button></div>}{!supabaseConfigured&&<div className="auth-status"><b>Backend setup pending</b><span>Add the school Supabase project URL and publishable key to the local environment to enable sign-in.</span><button className="secondary" onClick={()=>navigate('/portal/'+loginRole)}>Open {loginRole} demo portal <ChevronRight size={15}/></button></div>}{supabaseConfigured&&<form className="auth-form" onSubmit={submit}>{mode!=='reset'&&<label>{isStudentLogin?'School ID':'Email address'}<input type={isStudentLogin?'text':'email'} autoComplete={isStudentLogin?'username':'email'} placeholder={isStudentLogin?'MIC/2026/0001':'name@example.com'} value={email} onChange={e=>setEmail(e.target.value)} required/></label>}{mode!=='forgot'&&<><label>{mode==='reset'?'New password':'Password'}<input type={showPassword?'text':'password'} autoComplete={mode==='reset'?'new-password':'current-password'} value={password} onChange={e=>setPassword(e.target.value)} minLength={mode==='reset'?8:1} required/></label><button type="button" className="auth-text-button" onClick={()=>setShowPassword(value=>!value)}>{showPassword?'Hide password':'Show password'}</button></>}{mode==='reset'&&<ul className="auth-password-checks" aria-label="Password requirements">{[['length','At least 8 characters'],['uppercase','An uppercase letter'],['lowercase','A lowercase letter'],['number','A number'],['symbol','A symbol']].map(([key,label])=><li key={key} className={passwordChecks[key]?'met':''}><span aria-hidden="true">{passwordChecks[key]?'✓':'○'}</span>{label}</li>)}</ul>}{error&&<p className="auth-error" role="alert">{error}</p>}{notice&&<p className="auth-success" role="status">{notice}</p>}<button className="primary" type="submit" disabled={busy}>{busy?'Please wait…':mode==='sign-in'?'Sign in':mode==='forgot'?'Send recovery email':'Update password'} <ChevronRight size={16}/></button>{mode==='sign-in'&&isStudentLogin?<p className="auth-help">For a password reset, contact the school office.</p>:mode==='sign-in'?<button type="button" className="auth-text-button" onClick={()=>{setError('');setNotice('');setMode('forgot');}}>Forgot password?</button>:mode==='forgot'?<button type="button" className="auth-text-button" onClick={()=>setMode('sign-in')}>Back to sign in</button>:null}</form>}{/* Existing session details are used only when a valid recovery link has been opened. */}<div className="auth-footnote"><ShieldCheck size={16}/><span>Accounts are created by authorized school administrators. Role permissions are enforced by the connected database.</span></div></section></main>;
}
function PortalAuthGate({session,authReady,navigate}) { const [profile,setProfile]=useState(null);const [loading,setLoading]=useState(true);const [error,setError]=useState('');useEffect(()=>{let active=true;if(!authReady){setLoading(true);return()=>{active=false;};}if(!session){setProfile(null);setLoading(false);return()=>{active=false;};}setLoading(true);supabase.from('profiles').select('full_name,role').eq('id',session.user.id).single().then(({data,error:queryError})=>{if(!active)return;if(queryError){setError(queryError.message);setProfile(null);}else{setError('');setProfile(data);}setLoading(false);});return()=>{active=false;};},[session,authReady]);useEffect(()=>{if(authReady&&!session){const requestedRole=roleFromSlug(window.location.pathname.split('/')[2]);navigate('/login?role='+loginRoleForPortal(requestedRole));}},[authReady,session,navigate]);const signOut=async()=>{await supabase.auth.signOut();navigate('/login');};if(!authReady||loading||!session)return <main className="auth-page"><div className="auth-card"><p className="eyebrow blue">MAVERICK PORTAL</p><h1>Opening secure sign in…</h1></div></main>;if(error||!profile)return <main className="auth-page"><section className="auth-card"><h1>School profile unavailable</h1><p className="auth-intro">This account does not have an active school profile. Ask an authorized administrator to complete account setup.</p>{error&&<p className="auth-error">{error}</p>}<button className="secondary" onClick={signOut}>Sign out</button></section></main>;return <PortalWorkspace role={roleFromSlug(profile.role)} setRole={()=>{}} navigate={navigate} allowRoleSwitch={false} accountName={profile.full_name||session.user.email} accountEmail={session.user.email} onSignOut={signOut}/>;}
function RoleFeaturePanel({active,role,navigate,connected=false}) { const detail=featureDetails[active]; const fields=featureFields[active]; return <section className="panel feature"><span className="feature-icon"><ClipboardCheck/></span><p className="eyebrow blue">{connected?role.toUpperCase()+' ACCOUNT':role.toUpperCase()+' DEMO PREVIEW'}</p><h2>{detail?.[0]||active}</h2><p>{detail?.[1]||'This role-based section contains sample navigation only. The live system should expose records permitted to this role.'}</p>{fields&&<><h3 className="section-title">Record fields and workflow</h3><div className="subject-chips">{fields.map(field=><span key={field}>{field}</span>)}</div></>}<div className="portal-detail"><h3>{connected?'Workflow not connected yet':'Live system status'}</h3><p>{connected?'Your sign-in and database role are verified, but this feature does not yet read or write operational school records.':'This preview demonstrates the planned information architecture; it is not connected to school records.'} Record privacy and actions must be enforced by the backend.</p></div><div className="empty-actions"><button className="primary" onClick={()=>navigate('/contact')}>Contact the school <ChevronRight/></button><button className="secondary" onClick={()=>navigate('/portal')}>Portal information <ChevronRight/></button></div></section> }
function SiteFooter({navigate,openPortal}) { return <footer><div className="wrap footer-grid"><div><button className="footer-brand" onClick={()=>navigate('/')}><Crest small/><b>MAVERICK<br/>INTERNATIONAL COLLEGE</b></button><p>Empowering students to become scholars.</p></div><div><b>Explore</b>{[['About Maverick','/about'],['Academics','/academics'],['Admissions','/admissions'],['Student life','/student-life'],['Summer coaching','/summer-coaching'],['Clubs & societies','/clubs'],['Events calendar','/events'],['School announcements','/announcements'],['Academic calendar','/calendar'],['Assessment policy','/examinations'],['PTA','/pta'],['Student leadership','/student-leadership'],['Gallery','/gallery'],['Facilities','/facilities']].map(([t,u])=><button key={u} onClick={()=>navigate(u)}>{t}</button>)}</div><div><b>Contact</b><p>9, Ijero Street, Off Nnobi, Ikate-Kilo, Surulere, Lagos.</p><a href="tel:+2348132599917">+234 813 259 9917</a><br/><a href="tel:+2347018436958">+234 701 843 6958</a><br/><a href="mailto:maverickintlcollege1@gmail.com">maverickintlcollege1@gmail.com</a><a href="https://www.facebook.com/profile.php?id=61565548073644" target="_blank" rel="noreferrer">Official Facebook page</a><button onClick={()=>navigate('/contact')}>Contact page <ChevronRight size={14}/></button></div><div><b>Portal access</b>{[['Student','Student'],['Parent','Parent'],['Staff','Teacher']].map(([t,r])=><button key={r} onClick={()=>openPortal(r)}>{t} portal</button>)}</div></div><div className="copyright wrap">© 2026 Maverick International College. All rights reserved.</div></footer> }
function Portal({role,setRole,navigate}) { const [active,setActive]=useState('Overview'); const [clocked,setClocked]=useState(false); const nav=['Overview','My profile','Results','Timetable','Assignments','Announcements']; if(role==='Teacher') nav.splice(2,0,'Score entry','Attendance'); if(role==='Parent') nav.splice(2,0,'Children','Fees & payments'); if(role==='Administrator'||role==='Bursar') nav.splice(2,0,'Students','Academic records','Finance','Audit log'); const slug=item=>item==='Fees & payments'?'fees-payments':item.toLowerCase().replaceAll(' ','-'); const go=item=>{setActive(item); if(item==='Overview') navigate('/portal/'+role.toLowerCase()); else navigate('/portal/'+role.toLowerCase()+'/'+slug(item));}; const title=role==='Student'?'Welcome back, David.':role==='Parent'?'Good morning, Mrs. Adeyemi.':role==='Teacher'?'Good morning, Mr. Okafor.': 'Welcome, '+role+'.'; const sub=window.location.pathname.split('/')[3]; const selected=sub?nav.find(n=>slug(n)===sub)||decodeURIComponent(sub).replaceAll('-',' '):'Overview'; return <div className="portal"><aside><button className="brand side-brand" onClick={()=>navigate('/')}><Crest small/><span><b>MAVERICK</b><em>PORTAL</em></span></button><div className="user"><div className="avatar">{role[0]}</div><div><b>{role==='Student'?'David Adeyemi':role==='Parent'?'Mrs. Kemi Adeyemi':role==='Teacher'?'Mr. Chinedu Okafor':role}</b><small>{role} demo account</small></div></div><div className="side-nav">{nav.map((item,i)=><button key={item} className={selected===item?'active':''} onClick={()=>go(item)}>{React.createElement([LayoutDashboard,Users,GraduationCap,CalendarDays,ClipboardCheck,Bell,ReceiptText,ShieldCheck][i%8],{size:18})}{item}</button>)}</div><div className="switcher"><small>VIEW AS (DEMO)</small>{['Student','Parent','Teacher','Administrator','Bursar'].map(item=><button className={role===item?'selected':''} onClick={()=>{setRole(item);navigate('/portal/'+item.toLowerCase())}} key={item}>{item}</button>)}</div></aside><div className="portal-main"><div className="topbar"><div><button className="back" onClick={()=>navigate('/')}>← Website</button><p>Demo academic session · sample information</p></div><div className="top-actions"><button aria-label="Search" onClick={()=>go('Announcements')}><Search size={19}/></button><button className="notification" aria-label="Notifications" onClick={()=>go('Announcements')}><Bell size={19}/><i/></button><div className="avatar">{role[0]}</div>{onSignOut&&<button className="sign-out" onClick={onSignOut}>Sign out</button>}</div></div><section className="dashboard">{selected==='Overview'?<><div className="dashboard-heading"><div><p className="eyebrow blue">{role.toUpperCase()} DASHBOARD</p><h1>{title}</h1><p>Here is what is happening at Maverick today.</p></div>{role==='Teacher'&&<button className={clocked?'clocked':'clock'} onClick={()=>setClocked(!clocked)}><Clock3 size={18}/>{clocked?'Clock out':'Clock in'}</button>}</div><Overview role={role} navigate={navigate} go={go}/></>:<FeatureScreen active={selected} role={role} navigate={navigate}/>}</section></div></div> }
function Overview({role,navigate,go}) { const isStudent=role==='Student', isParent=role==='Parent', isTeacher=role==='Teacher'; return <><div className="stat-grid"><Stat label={isTeacher?'Classes today':isParent?'Children linked':isStudent?'Current average':'Active students'} value={isTeacher?'4':isParent?'2':isStudent?'78.4%':'684'} icon={isTeacher?BookOpen:isParent?Users:GraduationCap} detail={isStudent?'Excellent standing':'View details'}/><Stat label={isTeacher?'Scores pending':isParent?'Fee balance':isStudent?'Attendance':'Pending approvals'} value={isTeacher?'2':isParent?'₦45,000':isStudent?'94%':'12'} icon={isTeacher?ClipboardCheck:isParent?ReceiptText:CheckCircle2} detail={isStudent?'This term':'View details'}/><Stat label={isTeacher?'Next class':isParent?'Next event':isStudent?'Next class':'Staff present'} value={isTeacher?'SS2 Physics':isParent?'PTA Meeting':isStudent?'Mathematics':'92%'} icon={CalendarDays} detail={isTeacher?'10:30 AM':isParent?'1 Jun · 10 AM':isStudent?'10:30 AM':'Today'}/></div><div className="dashboard-grid"><section className="panel results"><div className="panel-title"><div><h3>{isTeacher?'Score completion':isParent?'Your children':isStudent?'Recent result summary':'Academic overview'}</h3><p>{isStudent?'Third Term · SS2 Science':isTeacher?'Third Term · assigned subjects':'2024/2025 Session'}</p></div><button className="link" onClick={()=>go(isTeacher?'Score entry':isParent?'Children':'Results')}>View all</button></div>{isTeacher?<div className="progress-list">{['SS2 Physics','SS1 Physics','JS3 Basic Science'].map((s,i)=><div key={s}><span><b>{s}</b><small>{[88,62,100][i]}% complete</small></span><div className="progress"><i style={{width:`${[88,62,100][i]}%`}}/></div></div>)}</div>:isParent?<div className="children"><div><div className="avatar blue-avatar">D</div><span><b>David Adeyemi</b><small>SS2 Science · 78.4% average</small></span><ChevronRight/></div><div><div className="avatar gold-avatar">A</div><span><b>Amara Adeyemi</b><small>JS2 Diamond · 82.1% average</small></span><ChevronRight/></div></div>:<table><thead><tr><th>Subject</th><th>Score</th><th>Grade</th></tr></thead><tbody>{subjects.map(s=><tr key={s[0]}><td>{s[0]}</td><td>{s[1]}%</td><td><span className={`grade ${s[2]}`}>{s[2]}</span></td></tr>)}</tbody></table>}</section><section className="panel notices"><div className="panel-title"><div><h3>Notice board</h3><p>Latest from the school</p></div><button className="link" onClick={()=>go('Announcements')}>View all</button></div>{notices.map(n=><div className="notice" key={n[0]}><span className="notice-dot"></span><div><small>{n[2]}</small><b>{n[0]}</b><p>{n[1]}</p></div></div>)}</section></div><section className="panel schedule"><div className="panel-title"><div><h3>{isTeacher?'Today’s teaching schedule':'Today’s timetable'}</h3><p>Monday, 20 May</p></div><button className="link" onClick={()=>go('Timetable')}>Full timetable</button></div><div className="schedule-row"><b>08:00</b><span><i className="blue-line"></i><b>{isTeacher?'SS1 Physics':'English Language'}</b><small>{isTeacher?'SS1 Emerald · Physics Lab':'SS2 Science · Room 12'}</small></span><b>09:20</b></div><div className="schedule-row"><b>10:30</b><span><i className="gold-line"></i><b>{isTeacher?'SS2 Physics':'Mathematics'}</b><small>{isTeacher?'SS2 Ruby · Physics Lab':'SS2 Science · Room 7'}</small></span><b>11:50</b></div></section></> }
function Stat({label,value,icon:Icon,detail}) {return <div className="stat"><span className="stat-icon"><Icon size={20}/></span><p>{label}</p><h2>{value}</h2><small>{detail} <ChevronRight size={13}/></small></div>}
function FeatureScreen({active,role,navigate}) { const titles={'My profile':'Profile and account details',Results:'Academic results',Timetable:'Weekly timetable',Assignments:'Learning tasks and submissions',Announcements:'School announcements',Children:'Linked learner profiles','Fees & payments':'Fee statements and payment guidance','Score entry':'Teacher score entry',Attendance:'Class attendance',Students:'Student directory','Academic records':'Academic records and reviews',Finance:'Finance overview','Audit log':'Administrative activity log'}; const copy={Results:'Review approved assessment summaries by subject and term. Sample figures are illustrative and are not official learner records.',Timetable:'A weekly view of lessons, rooms and school activities. Confirm timetable changes through the school office.',Announcements:'Notices and reminders shared with the school community. Contact the office if you need clarification.','Fees & payments':'View a sample fee balance and contact the bursary for current statements, approved payment channels and receipts.',Assignments:'A place for class tasks, due dates and guidance from teachers. Submission workflows require the live school system.'}; return <section className="panel feature"><span className="feature-icon"><ClipboardCheck/></span><p className="eyebrow blue">{role.toUpperCase()} DEMO</p><h2>{titles[active]||active}</h2><p>{copy[active]||'This role-based page shows the information and workflows intended for this section. Live records and submissions are not connected in this website preview.'}</p><div className="portal-detail"><h3>{active} overview</h3><p>Use this section to review relevant information, follow school guidance and contact the appropriate staff member when an update is required.</p><ul><li>Sample content is for demonstration only.</li><li>Official records are managed by authorized school staff.</li><li>Contact the school office for current information or assistance.</li></ul></div><div className="empty-actions"><button className="primary" onClick={()=>navigate('/contact')}>Contact the school <ChevronRight/></button><button className="secondary" onClick={()=>navigate('/portal')}>Portal information <ChevronRight/></button></div></section> }
createRoot(document.getElementById('root')).render(<App/>);
